BEGIN;

UPDATE "Products" product
SET "AttributesJson" = (product."AttributesJson"::jsonb || jsonb_build_object(
    'network', CASE WHEN lower(COALESCE(product."AttributesJson"::jsonb ->> 'supports5G', 'false')) = 'true' THEN '5G' ELSE '4G' END
))::text
WHERE product."IsActive"
  AND product."AttributesJson"::jsonb ? 'supports5G'
  AND NOT product."AttributesJson"::jsonb ? 'network'
  AND EXISTS (
      SELECT 1 FROM "Categories" category
      JOIN "Categories" root ON root."Id" = category."ParentCategoryId"
      WHERE category."Id" = product."CategoryId"
        AND lower(trim(root."Name")) = 'mobiles'
        AND root."ParentCategoryId" IS NULL
  );

WITH seed("RootName", "ParentName", "CategoryName", "Name", "Brand", "Description", "Price", "StockQuantity", "ImageUrl", "AttributesJson") AS (VALUES
