    ('Food', NULL, 'Beverages', 'Organic India Tulsi Green Tea 25 Bags', 'Organic India', 'Green tea bags blended with tulsi for a light aromatic daily infusion.', 199, 21, 'https://images.unsplash.com/photo-1556881286-fc6915169721?w=700&auto=format&fit=crop&q=80', '{"productType":"Green Tea","foodType":"Beverages","dietary":"Vegan","packSize":"25 bags"}'),
    ('Food', NULL, 'Chocolates', 'Amul 75% Dark Chocolate Bar 150g', 'Amul', 'Dark chocolate bar with a pronounced cocoa taste in a 150g pack.', 180, 30, 'https://images.unsplash.com/photo-1606313564200-e75d5e30476c?w=700&auto=format&fit=crop&q=80', '{"productType":"Dark Chocolate","foodType":"Chocolate","dietary":"Vegetarian","packSize":"150 g"}')
), resolved AS (
    SELECT seed.*, category."Id" AS "CategoryId"
    FROM seed
    JOIN "Categories" root
      ON root."ParentCategoryId" IS NULL
     AND lower(trim(root."Name")) = lower(trim(seed."RootName"))
    JOIN "Categories" category
      ON lower(trim(category."Name")) = lower(trim(seed."CategoryName"))
     AND (
       (seed."ParentName" IS NULL AND category."ParentCategoryId" = root."Id")
       OR (seed."ParentName" IS NOT NULL AND EXISTS (
         SELECT 1 FROM "Categories" parent
         WHERE parent."Id" = category."ParentCategoryId"
           AND lower(trim(parent."Name")) = lower(trim(seed."ParentName"))
           AND parent."ParentCategoryId" = root."Id"
       ))
       OR (seed."ParentName" IS NULL AND category."Id" = root."Id")
     )
)
INSERT INTO "Products" ("CategoryId", "Name", "Brand", "Description", "Price", "StockQuantity", "ImageUrl", "AttributesJson", "IsActive", "CreatedAt")
SELECT resolved."CategoryId", resolved."Name", resolved."Brand", resolved."Description", resolved."Price", resolved."StockQuantity", resolved."ImageUrl", resolved."AttributesJson", true, CURRENT_TIMESTAMP
FROM resolved
WHERE NOT EXISTS (
    SELECT 1 FROM "Products" existing
    WHERE existing."CategoryId" = resolved."CategoryId"
      AND lower(trim(existing."Name")) = lower(trim(resolved."Name"))
);

COMMIT;
